const responseData = pm.response.json();

// 1. Status code validation
pm.test("Status code should be 200", function () {
    pm.response.to.have.status(200);
});

// 2. Response should be an array
pm.test("Response should be an array", function () {
    pm.expect(responseData).to.be.an("array");
});

// 3. Users array should not be empty
pm.test("Users array should not be empty", function () {
    pm.expect(responseData.length).to.be.greaterThan(0);
});

// 4. Validate required fields
pm.test("Each user should have id, name and email", function () {
    responseData.forEach((user) => {
        pm.expect(user.id).to.exist;
        pm.expect(user.name).to.be.a("string").and.not.empty;
        pm.expect(user.email).to.be.a("string").and.not.empty;
    });
});

// 5. Save User ID and Phone in local variables
if (responseData.length > 0) {
    pm.variables.set("userId", responseData[0].id);
    pm.variables.set("userPhone", responseData[0].phone);
}

// 6. Verify User ID is saved
pm.test("User ID should be saved", function () {
    pm.expect(pm.variables.get("userId")).to.exist;
});

const ts = Date.now();
pm.variables.set("updatedName", "Test User " + ts);
pm.variables.set("updatedEmail", "user" + ts + "@example.com");
pm.variables.set("updatedCompany", "Company " + ts);

pm.test("Status code should be 200", function () {
    pm.response.to.have.status(200);
});

const res = pm.response.json();

pm.test("Returned ID should match saved userId", function () {
    pm.expect(String(res.id)).to.eql(String(pm.variables.get("userId")));
});

pm.test("Phone should not be empty", function () {
    pm.expect(res.phone).to.be.a("string").and.not.empty;
    pm.expect(res.phone).to.not.include("{{");
});

pm.test("Returned name should match updated name", function () {
    pm.expect(res.name).to.eql(pm.variables.get("updatedName"));
});
